import{_ as a,o as r,c as e,a2 as o}from"./chunks/framework.wVcpyw2-.js";const c=JSON.parse('{"title":"跑腿","description":"灵萌跑腿配置：跑腿区域配置、订单处理，以及用 UI 编辑器搭建可配置服务表单的步骤。","frontmatter":{"title":"跑腿","description":"灵萌跑腿配置：跑腿区域配置、订单处理，以及用 UI 编辑器搭建可配置服务表单的步骤。"},"headers":[],"relativePath":"features/errand.md","filePath":"features/errand.md","lastUpdated":1785051348000}'),i={name:"features/errand.md"};function l(d,t,n,s,h,u){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="跑腿" tabindex="-1">跑腿 <a class="header-anchor" href="#跑腿" aria-label="Permalink to &quot;跑腿&quot;">​</a></h1><p>跑腿有两条常见玩法：</p><ol><li><strong>标准跑腿区域配置</strong>（商户管理里的区域规则 + 订单）</li><li><strong>可配置服务表单</strong>（UI 编辑器拖表单：帮取、代办、预约等，带计价公式）</li></ol><p>两者都依赖地图与支付；派单通常与 <a href="/features/rider">骑手</a> 共用。</p><div class="warning custom-block"><p class="custom-block-title">菜单位置</p><p>跑腿相关菜单挂在 <strong>商户管理 → 外卖</strong> 分组下。该分组可能显示「内测中」，见 <a href="/features/takeaway">外卖</a>。</p></div><hr><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><ul><li>跑腿 / 相关模块已开通（<a href="/config/my-modules">我的模块</a>）</li><li><a href="/features/map">高德地图</a>、<a href="/features/payment">支付</a> 已配置</li><li>若需骑手履约：完成 <a href="/features/rider">骑手</a> 审核上线</li></ul><hr><h2 id="玩法-a-跑腿区域配置" tabindex="-1">玩法 A：跑腿区域配置 <a class="header-anchor" href="#玩法-a-跑腿区域配置" aria-label="Permalink to &quot;玩法 A：跑腿区域配置&quot;">​</a></h2><h3 id="_1-配置区域" tabindex="-1">1. 配置区域 <a class="header-anchor" href="#_1-配置区域" aria-label="Permalink to &quot;1. 配置区域&quot;">​</a></h3><p>路径：<strong>商户管理 → 外卖 → 跑腿区域配置</strong></p><p>为每个区域设置（字段以页面为准）：</p><table tabindex="0"><thead><tr><th>方向</th><th>说明</th></tr></thead><tbody><tr><td>是否启用跑腿</td><td>总开关</td></tr><tr><td>服务范围</td><td>距离或边界</td></tr><tr><td>基础价 / 里程费 / 时段加价</td><td>计价</td></tr><tr><td>物品类型、重量上限等</td><td>下单约束</td></tr></tbody></table><p>保存后，该区域用户端出现跑腿入口（还取决于 UI 是否配置入口）。</p><h3 id="_2-跑腿订单" tabindex="-1">2. 跑腿订单 <a class="header-anchor" href="#_2-跑腿订单" aria-label="Permalink to &quot;2. 跑腿订单&quot;">​</a></h3><p>路径：<strong>商户管理 → 外卖 → 跑腿订单</strong></p><p>查看进行中/已完成订单，处理异常、取消、退款（需相应权限）。</p><p>与外卖订单分开：外卖看 <strong>外卖订单</strong>，跑腿看 <strong>跑腿订单</strong>。</p><hr><h2 id="玩法-b-可配置服务表单-推荐做特色业务" tabindex="-1">玩法 B：可配置服务表单（推荐做特色业务） <a class="header-anchor" href="#玩法-b-可配置服务表单-推荐做特色业务" aria-label="Permalink to &quot;玩法 B：可配置服务表单（推荐做特色业务）&quot;">​</a></h2><p>适合：帮取快递、代办登记、预约服务等——每种服务一张表单页，运营可自己改字段和计价。</p><h3 id="步骤" tabindex="-1">步骤 <a class="header-anchor" href="#步骤" aria-label="Permalink to &quot;步骤&quot;">​</a></h3><ol><li>打开 <strong>UI管理 → 页面配置</strong></li><li><strong>新建</strong> 页面，类型选 <strong>服务表单</strong></li><li>进入 <strong>设计</strong>：从左侧只添加「表单/服务」类组件（输入、地址、选项、提交底栏等）</li><li>点击画布空白，在右侧 <strong>服务表单</strong> Tab 配置：履约方式、基础价、计价方式/公式</li><li>必须包含 <strong>提交底栏</strong>（每页唯一）</li><li><strong>保存</strong> → 在列表中 <strong>启用</strong></li><li>用金刚区/按钮等配置 <strong>点击动作</strong> 跳到该页（见 <a href="/features/ui-editor/styles-and-actions">样式与点击动作</a>）</li></ol><p>完整组件说明：<a href="/features/ui-editor/components-form">表单/服务组件</a><br> 上手：<a href="/features/ui-editor/getting-started">UI 编辑器快速上手</a></p><p>保存启用后，系统会把表单同步为跑腿侧可用的服务模板（运营无需改代码）。</p><hr><h2 id="区域关系" tabindex="-1">区域关系 <a class="header-anchor" href="#区域关系" aria-label="Permalink to &quot;区域关系&quot;">​</a></h2><table tabindex="0"><thead><tr><th>配置</th><th>说明</th></tr></thead><tbody><tr><td>跑腿区域配置</td><td>标准跑腿按 region 独立开关与计价</td></tr><tr><td>区域外卖配置</td><td>与跑腿相互独立，可只开其一</td></tr><tr><td>服务表单页</td><td>也可按区域保存页面配置</td></tr></tbody></table><p>地图 Key 全站共用；范围与价格按区域/页面分别填。</p><hr><h2 id="验证是否生效" tabindex="-1">验证是否生效 <a class="header-anchor" href="#验证是否生效" aria-label="Permalink to &quot;验证是否生效&quot;">​</a></h2><h3 id="标准跑腿" tabindex="-1">标准跑腿 <a class="header-anchor" href="#标准跑腿" aria-label="Permalink to &quot;标准跑腿&quot;">​</a></h3><ol><li>区域配置已启用并设简单计价</li><li>客户端能填写取送地址、算出费用并支付</li><li><strong>跑腿订单</strong> 出现新单；骑手可接单流转</li></ol><h3 id="服务表单" tabindex="-1">服务表单 <a class="header-anchor" href="#服务表单" aria-label="Permalink to &quot;服务表单&quot;">​</a></h3><ol><li>页面已启用，入口跳转正确</li><li>必填项校验生效，价格随选项变化（若配了加价）</li><li>提交并支付成功，后台能查到对应订单/单据</li></ol><hr><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>处理</th></tr></thead><tbody><tr><td>没有跑腿入口</td><td>区域未启用；UI 未配入口；模块未开</td></tr><tr><td>费用为 0 或算不出</td><td>地图 Key；起终点超范围；计价公式未配</td></tr><tr><td>无人接单</td><td>与外卖相同，检查骑手在线与派单</td></tr><tr><td>服务表单组件是灰的</td><td>页面类型不是「服务表单」</td></tr></tbody></table><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/features/takeaway">外卖</a></li><li><a href="/features/rider">骑手</a></li><li><a href="/features/ui-editor/components-form">UI 编辑器 · 服务表单</a></li><li><a href="/features/map">地图与定位</a></li></ul>',42)])])}const b=a(i,[["render",l]]);export{c as __pageData,b as default};
